#include <iostream>
#include <stdexcept>
#include <string>

class Resource {
    std::string name;
public:
    explicit Resource(std::string n) : name(std::move(n)) {
        std::cout << "Constructed: " << name << "\n";
    }
    ~Resource() {
        std::cout << "Destroyed: " << name << "\n";
    }
};

class Composite {
    Resource r1;
    Resource r2;
public:
    Composite() : r1("Member-1"), r2("Member-2") {
        std::cout << "Composite constructor throwing exception...\n";
        throw std::runtime_error("Initialization failure in Composite");
    }
    ~Composite() {
        std::cout << "Destroyed Composite\n"; // Will never execute
    }
};

void deepNested() {
    Resource local("Local-In-DeepNested");
    std::cout << "deepNested throwing conditional result...\n";
    // Ternary operator evaluates (true ? 3.14 : 42), promoting int 42 to double 42.0
    throw (true ? 3.14 : 42);
}

void intermediary() {
    try {
        deepNested();
    } catch (int) {
        std::cout << "Caught int in intermediary (unexpected)\n";
    } catch (double d) {
        std::cout << "Caught double (" << d << ") in intermediary, rethrowing...\n";
        throw; // Rethrow exact exception
    }
}

int main() {
    // Part 1: Constructor failure and member unwinding
    std::cout << "--- Test 1: Constructor Failure ---\n";
    try {
        Composite comp;
    } catch (const std::exception& e) {
        std::cout << "Caught in main: " << e.what() << "\n";
    }

    // Part 2: Ternary promotion, unwinding across levels, and rethrowing
    std::cout << "\n--- Test 2: Unwinding, Ternary Type, and Rethrow ---\n";
    try {
        intermediary();
    } catch (const double d) {
        std::cout << "Caught rethrown double in main: " << d << "\n";
    } catch (...) {
        std::cout << "Caught generic fallback\n";
    }

    return 0;
}
